import java.io.*;import java.util.*;public class gen{static Random r=new Random(2462026);static void heap(long[]a,int n){for(int i=n/2-1;i>=0;i--)down(a,n,i);}static void down(long[]a,int n,int i){while(true){int x=i,l=2*i+1,q=2*i+2;if(l<n&&a[l]<a[x])x=l;if(q<n&&a[q]<a[x])x=q;if(x==i)return;long t=a[i];a[i]=a[x];a[x]=t;i=x;}}public static void main(String[]x)throws Exception{for(int t=0;t<100;t++){int n=t==0?1:t==1?2:t==2?3:t==99?1000:4+r.nextInt(97);long[]a=new long[n];for(int i=0;i<n;i++)a[i]=(t%10==0?5:t%10==1?i-n/2:t%10==2?r.nextInt(21)-10:r.nextInt(2001)-1000);heap(a,n);PrintWriter p=new PrintWriter(String.format("Testcases/Input/input%02d.txt",t));p.println(n);for(int i=0;i<n;i++){if(i>0)p.print(' ');p.print(a[i]);}p.println();p.close();}}}